package it.nuovoordine.complete;

import net.minecraftforge.fml.common.Mod;

import java.lang.reflect.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

@Mod("nocomplete")
public final class NuovoOrdineCompleteMod {
    private static final System.Logger LOG=System.getLogger("nocomplete");
    private static final String VERSION="1.0.0";
    private final Config cfg=new Config(Path.of("config","nuovoordine-complete.properties"));
    private final StateStore store=new StateStore(Path.of("config","nuovoordine-complete-state.dat.gz"));
    private final EconomyBridge economy=new EconomyBridge();
    private final TownyBridge towny=new TownyBridge();
    private final HubServer hub=new HubServer();
    private Models.State state=store.load();
    private volatile Object server;
    private long lastSecond=-1,lastSaveAt=0;
    private boolean dirty;
    private final Map<UUID,Models.Treatment> treatments=new HashMap<>();
    private final Map<UUID,Models.Loc> lastMtsLoc=new HashMap<>();
    private final Map<UUID,String> activeVehicle=new HashMap<>();
    private final Set<UUID> internalDamage=new HashSet<>();
    private Models.Loc lastDriverLoc;

    public NuovoOrdineCompleteMod(){
        int hooks=0;
        hooks+=ForgeBridge.on("net.minecraftforge.event.server.ServerStartedEvent",this::serverStarted)?1:0;
        hooks+=ForgeBridge.on("net.minecraftforge.event.server.ServerStoppingEvent",this::serverStopping)?1:0;
        hooks+=ForgeBridge.on("net.minecraftforge.event.TickEvent$ServerTickEvent",this::serverTick)?1:0;
        hooks+=ForgeBridge.on("net.minecraftforge.event.RegisterCommandsEvent",this::registerCommands)?1:0;
        hooks+=ForgeBridge.on("net.minecraftforge.event.entity.player.PlayerEvent$PlayerLoggedInEvent",this::playerLogin)?1:0;
        hooks+=ForgeBridge.on("net.minecraftforge.event.entity.player.PlayerEvent$PlayerLoggedOutEvent",this::playerLogout)?1:0;
        hooks+=ForgeBridge.on("net.minecraftforge.event.entity.living.LivingDamageEvent",this::livingDamage)?1:0;
        hooks+=ForgeBridge.on("net.minecraftforge.event.entity.living.LivingDeathEvent",this::livingDeath)?1:0;
        LOG.log(System.Logger.Level.INFO,"Nuovo Ordine Complete "+VERSION+" inizializzato: "+hooks+" hook Forge");
    }

    private synchronized void serverStarted(Object event){
        try{server=R.call(event,"getServer");}catch(Exception e){LOG.log(System.Logger.Level.ERROR,"Server non disponibile",e);return;}
        long now=System.currentTimeMillis();
        if(state.nextStrategicEventAt<=now)state.nextStrategicEventAt=now+min("event.everyMinutes",45)*60_000L;
        if(state.nextAirdropAt<=now)state.nextAirdropAt=now+min("airdrop.everyMinutes",90)*60_000L;
        if(state.nextConvoyAt<=now)state.nextConvoyAt=now+min("convoy.everyMinutes",120)*60_000L;
        if(cfg.b("hub.enabled",true))hub.start(cfg.s("hub.bind","0.0.0.0"),cfg.i("hub.port",8765,1024,65535),cfg.s("hub.cors","*"),this::hubJson);
        applyTaczShootCompatibilityFix();
        broadcast("§8[§cNuovo Ordine§8] §7Complete §f"+VERSION+" §7attivo. Towny="+(townyAvailable()?"§aOK":"§eFallback")+" §7Economia="+(economy.ready()?"§aVault/TNE OK":"§cnon trovata"));
        dirty=true;save();
    }
    private synchronized void serverStopping(Object e){save();hub.stop();server=null;treatments.clear();lastMtsLoc.clear();activeVehicle.clear();}
    private void playerLogin(Object event){try{Object p=R.call(event,"getEntity");stat(p);send(p,"§7Nuovo Ordine: §f/no status §7per eventi, contratti e classifica.");}catch(Exception ignored){}}
    private void playerLogout(Object event){try{UUID id=R.uuid(R.call(event,"getEntity"));treatments.remove(id);lastMtsLoc.remove(id);}catch(Exception ignored){}}

    private void serverTick(Object event){
        if(server==null||!endPhase(event))return;long tick=serverTickCount();if(tick<0||tick/20==lastSecond)return;lastSecond=tick/20;long now=System.currentTimeMillis();
        synchronized(this){
            tickStrategic(now);tickEvents(now);tickInfluence(now);tickInjuries(now);tickTreatments(now);tickAirdrop(now);tickConvoy(now);tickVehicleKm(now);tickExpiry(now);
            int saveEvery=cfg.i("state.saveEverySeconds",15,5,300);if(dirty&&(now-lastSaveAt>=saveEvery*1000L))save();
        }
    }

    private boolean endPhase(Object e){try{return "END".equals(String.valueOf(R.field(e,"phase")));}catch(Exception x){return true;}}
    private long serverTickCount(){try{return R.lng(R.call(server,"getTickCount"));}catch(Exception e){try{return R.lng(R.call(server,"m_129928_"));}catch(Exception ignored){return -1;}}}

    private synchronized void registerCommands(Object event){
        try{Object dispatcher=R.call(event,"getDispatcher");for(String rootName:List.of("nuovoordine","no")){Object root=ForgeBridge.literal(rootName);ForgeBridge.executes(root,(src,ctx)->{command(src,"");return 1;});Object arg=ForgeBridge.greedyArg("args");ForgeBridge.executes(arg,(src,ctx)->{command(src,ForgeBridge.arg(ctx,"args"));return 1;});ForgeBridge.then(root,arg);for(Method m:dispatcher.getClass().getMethods())if(m.getName().equals("register")&&m.getParameterCount()==1){m.invoke(dispatcher,root);break;}}}
        catch(Throwable t){LOG.log(System.Logger.Level.ERROR,"Comandi non registrati",t);}
    }

    private void command(Object source,String raw){
        List<String> a=tokens(raw);if(a.isEmpty()){help(source);return;}String c=a.get(0).toLowerCase(Locale.ROOT);
        try{
            switch(c){
                case "help","aiuto"->help(source);case "status"->status(source);case "ranking","classifica"->ranking(source,a.size()>1?a.get(1):"influence");case "stats"->stats(source,a);case "rep","reputazione"->rep(source,a);
                case "point","punto"->pointCmd(source,a);case "event","evento"->eventCmd(source,a);case "contract","contratto","contratti"->contractCmd(source,a);case "airdrop"->airdropCmd(source,a);
                case "convoy","convoglio"->convoyCmd(source,a);case "garage","veicolo","veicoli"->garageCmd(source,a);case "used","usato"->usedCmd(source,a);case "bandage","bendaggio"->startTreatment(source,"bandage");case "medical","medico"->startTreatment(source,"medical");
                case "reload"->{requireOp(source);cfg.load();msg(source,"§aConfigurazione ricaricata.");}
                case "save"->{requireOp(source);save();msg(source,"§aStato salvato.");}
                default->msg(source,"§cComando sconosciuto. Usa §f/no help§c.");
            }
        }catch(Exception e){msg(source,"§c"+R.root(e));}
    }

    private void help(Object s){
        msg(s,"§8§m--------------- §cNuovo Ordine §8§m---------------");
        msg(s,"§f/no status §8| §f/no ranking [influence|kills|contracts|loot|wealth|rep|vehicles]");
        msg(s,"§f/no rep §8| §f/no stats §8| §f/no contratti list/mine/post/accept/deliver/approve/cancel");
        msg(s,"§f/no airdrop status/claim §8| §f/no convoy status/join/claim");
        msg(s,"§f/no garage list/insure/prepare §8| §f/no usato list/sell/buy/cancel");
        msg(s,"§f/no bendaggio §8| §f/no medico");
        if(isOp(s))msg(s,"§cOP: §f/no point add/remove/list; /no event start; /no airdrop add/start; /no convoy startpoint/endpoint/start; /no garage grant; /no rep set; /no reload");
    }

    private void status(Object s){long now=System.currentTimeMillis();msg(s,"§8§m--------------- §cNuovo Ordine §8§m---------------");msg(s,"§7Punti: §f"+state.points.size()+" §8| §7Contratti aperti: §f"+state.contracts.values().stream().filter(x->x.status==Models.ContractStatus.OPEN).count()+" §8| §7Usato: §f"+state.usedListings.size());
        if(state.eventEndsAt>now&&state.points.containsKey(state.eventPoint))msg(s,"§6Evento caldo: §e"+state.points.get(state.eventPoint).name+" §7("+minsLeft(state.eventEndsAt,now)+"m)");else msg(s,"§7Prossimo evento strategico: §f"+minsLeft(state.nextStrategicEventAt,now)+"m");
        if(activeAirdrop(now))msg(s,"§bAirdrop attivo: §f"+dropPoint().name+" §7("+minsLeft(state.airdrop.expiresAt,now)+"m)");else msg(s,"§7Prossimo airdrop: §f"+minsLeft(state.nextAirdropAt,now)+"m");
        msg(s,"§7Convoglio: §f"+state.convoy.phase+(state.convoy.routeId.isBlank()?"":" §7route §f"+state.convoy.routeId));
    }

    private void ranking(Object s,String type){type=type.toLowerCase(Locale.ROOT);if(type.equals("influence")){rankMap(s,"Influenza",state.influence);return;}List<Map.Entry<UUID,StatsView>> rows=new ArrayList<>();for(var e:state.stats.entrySet()){Models.Stats st=e.getValue();double value=switch(type){case "kills"->st.kills;case "contracts"->st.contracts;case "loot"->st.loot;case "vehicles"->vehicleCount(e.getKey());case "wealth"->{double b=economy.balance(e.getKey());yield Double.isNaN(b)?0:b;}case "rep"->{Models.Rep r=state.reputation.getOrDefault(e.getKey(),new Models.Rep());yield r.civil+r.military-r.criminal;}default->-1;};if(value>=0)rows.add(Map.entry(e.getKey(),new StatsView(st.lastName,value)));}rows.sort((x,y)->Double.compare(y.getValue().value,x.getValue().value));msg(s,"§6Classifica "+type+":");for(int i=0;i<Math.min(10,rows.size());i++){var r=rows.get(i).getValue();msg(s,"§e"+(i+1)+". §f"+r.name+" §7— §6"+format(r.value));}if(rows.isEmpty())msg(s,"§7Nessun dato.");}
    private record StatsView(String name,double value){}
    private void rankMap(Object s,String title,Map<String,Long> map){List<Map.Entry<String,Long>> l=new ArrayList<>(map.entrySet());l.sort((a,b)->Long.compare(b.getValue(),a.getValue()));msg(s,"§6Classifica "+title+":");if(l.isEmpty())msg(s,"§7Nessun dato.");for(int i=0;i<Math.min(10,l.size());i++){var e=l.get(i);int stars=state.legacy.getOrDefault(e.getKey(),0);msg(s,"§e"+(i+1)+". §f"+e.getKey()+" §7— §6"+e.getValue()+(stars>0?" §d★"+stars:""));}}

    private void stats(Object s,List<String>a)throws Exception{Object p=player(s);Models.Stats st=stat(p);msg(s,"§6Statistiche di §f"+st.lastName+"§6: §7K/D §f"+st.kills+"/"+st.deaths+" §8| §7Contratti §f"+st.contracts+" §8| §7Loot §f"+st.loot+" §8| §7Convogli §f"+st.convoys+" §8| §7Airdrop §f"+st.airdrops+" §8| §7MTS km §f"+String.format(Locale.ROOT,"%.2f",st.mtsKm));}
    private void rep(Object s,List<String>a)throws Exception{if(a.size()>=5&&a.get(1).equalsIgnoreCase("set")){requireOp(s);Object target=findPlayer(a.get(2));if(target==null)throw new IllegalArgumentException("Player online non trovato");Models.Rep r=repOf(R.uuid(target));int v=Integer.parseInt(a.get(4));switch(a.get(3).toLowerCase(Locale.ROOT)){case"civil"->r.civil=v;case"criminal"->r.criminal=v;case"military"->r.military=v;default->throw new IllegalArgumentException("Usa civil/criminal/military");}dirty=true;msg(s,"§aReputazione aggiornata.");return;}Object p=player(s);Models.Rep r=repOf(R.uuid(p));msg(s,"§6Reputazione §f"+R.name(p)+"§6: §aCivile "+r.civil+" §8| §cCriminale "+r.criminal+" §8| §bMilitare "+r.military);}

    private void pointCmd(Object s,List<String>a)throws Exception{if(a.size()==1||a.get(1).equalsIgnoreCase("list")){listPoints(s);return;}requireOp(s);switch(a.get(1).toLowerCase(Locale.ROOT)){case"add"->{Object p=player(s);String id=a.size()>2?safeId(a.get(2)):nextId("p",state.points.keySet());String name=a.size()>3?join(a,3):"Punto Strategico "+id;Models.Loc l=R.loc(p);l.name=name;state.points.put(id,new Models.Point(id,name,l,cfg.i("strategic.defaultRadius",25,5,256)));dirty=true;save();msg(s,"§aCreato §f"+name+" §7("+id+")§a.");}case"remove"->{Object p=player(s);Models.Loc l=R.loc(p);Models.Point best=null;double d=50*50;for(Models.Point x:state.points.values()){double q=x.loc.dist2(l.dimension,l.x,l.y,l.z);if(q<=d){d=q;best=x;}}if(best==null)throw new IllegalArgumentException("Nessun punto entro 50 blocchi");state.points.remove(best.id);dirty=true;msg(s,"§aRimosso §f"+best.name);}default->throw new IllegalArgumentException("/no point add [id] [nome] | remove | list");}}
    private void listPoints(Object s){int cap=cfg.i("captureSeconds",120,10,3600);if(state.points.isEmpty()){msg(s,"§7Nessun punto strategico.");return;}for(Models.Point p:state.points.values())msg(s,"§e"+p.id+" §f"+p.name+" §8| §7owner §f"+(p.owner.isBlank()?"neutrale":p.owner)+(p.candidate.isBlank()?"":" §8| §e"+p.candidate+" "+p.progress+"/"+cap+"s"));}
    private void eventCmd(Object s,List<String>a){if(a.size()>1&&a.get(1).equalsIgnoreCase("start")){requireOp(s);startStrategicEvent(System.currentTimeMillis());}else status(s);}

    private void contractCmd(Object s,List<String>a)throws Exception{
        if(a.size()==1||a.get(1).equalsIgnoreCase("list")){contractList(s,false);return;}String sub=a.get(1).toLowerCase(Locale.ROOT);Object p=player(s);UUID id=R.uuid(p);String name=R.name(p);
        switch(sub){
            case"mine"->contractList(s,true);
            case"post"->{if(a.size()<5)throw new IllegalArgumentException("/no contract post <bounty|delivery|vehicle|transport|escort|capture|eliminate> <reward> <target/descrizione>");String type=a.get(2).toLowerCase(Locale.ROOT);if(!Set.of("bounty","delivery","vehicle","transport","escort","capture","eliminate").contains(type))throw new IllegalArgumentException("Tipo non valido");double reward=Double.parseDouble(a.get(3));if(reward<=0||reward>100_000_000)throw new IllegalArgumentException("Ricompensa non valida");String target=join(a,4);if(type.equals("delivery")&&!target.matches("[a-z0-9_.-]+:[a-z0-9_/.-]+:[0-9]+"))throw new IllegalArgumentException("Delivery: target deve essere mod:item:quantita");if(!economy.withdraw(id,reward))throw new IllegalArgumentException("Saldo insufficiente o Vault/TNE non disponibile");Models.Contract c=new Models.Contract();c.id=shortId();c.type=type;c.creator=id;c.creatorName=name;c.creatorFaction=towny.faction(p);c.reward=reward;c.target=target;c.description=target;c.createdAt=System.currentTimeMillis();c.expiresAt=c.createdAt+cfg.l("contract.expireHours",168,1,720)*3600_000L;state.contracts.put(c.id,c);stat(p).moneySpent+=reward;dirty=true;broadcast("§8[§eContratti§8] §f"+name+" §7ha pubblicato §e"+c.type+" §7#§f"+c.id+" §7— premio §a$"+money(reward));}
            case"accept"->{Models.Contract c=contract(a,2);if(c.status!=Models.ContractStatus.OPEN)throw new IllegalArgumentException("Contratto non disponibile");if(id.equals(c.creator))throw new IllegalArgumentException("Non puoi accettare il tuo contratto");c.acceptor=id;c.acceptorName=name;c.acceptorFaction=towny.faction(p);c.status=Models.ContractStatus.ACCEPTED;dirty=true;msg(s,"§aContratto §f#"+c.id+" §aaccettato.");}
            case"deliver"->{Models.Contract c=contract(a,2);ensureAcceptor(c,id);if(!c.type.equals("delivery"))throw new IllegalArgumentException("Non è una consegna materiali");String t=c.target;int last=t.lastIndexOf(':');String item=t.substring(0,last);int count=Integer.parseInt(t.substring(last+1));int have=runCommand("clear "+name+" "+item+" 0");if(have<count)throw new IllegalArgumentException("Servono "+count+"x "+item+" (hai "+have+")");int removed=runCommand("clear "+name+" "+item+" "+count);if(removed<=0)throw new IllegalArgumentException("Impossibile rimuovere gli oggetti");completeContract(c,p);}
            case"approve"->{Models.Contract c=contract(a,2);if(!id.equals(c.creator))throw new IllegalArgumentException("Solo il committente può approvare");if(c.status!=Models.ContractStatus.ACCEPTED)throw new IllegalArgumentException("Contratto non accettato");if(Set.of("bounty","eliminate","delivery","capture").contains(c.type))throw new IllegalArgumentException("Questo contratto si completa automaticamente");Object accepter=findPlayer(c.acceptorName);if(accepter==null)throw new IllegalArgumentException("Esecutore non online");completeContract(c,accepter);}
            case"cancel"->{Models.Contract c=contract(a,2);if(!id.equals(c.creator))throw new IllegalArgumentException("Solo il committente può annullare");if(c.status!=Models.ContractStatus.OPEN)throw new IllegalArgumentException("Puoi annullare solo un contratto non accettato");double fee=c.reward*cfg.d("contract.cancelFeePercent",2,0,50)/100.0;double refund=c.reward-fee;if(!economy.deposit(c.creator,refund))throw new IllegalArgumentException("Rimborso fallito: contratto lasciato aperto");c.status=Models.ContractStatus.CANCELLED;state.totalMoneySunk+=Math.round(fee);dirty=true;msg(s,"§eContratto annullato. Rimborso §a$"+money(refund)+" §7commissione §c$"+money(fee));}
            default->throw new IllegalArgumentException("Subcomando contratto non valido");
        }
    }
    private Models.Contract contract(List<String>a,int idx){if(a.size()<=idx)throw new IllegalArgumentException("ID contratto mancante");Models.Contract c=state.contracts.get(a.get(idx));if(c==null)throw new IllegalArgumentException("Contratto non trovato");return c;}
    private void contractList(Object s,boolean mine)throws Exception{UUID me=R.uuid(player(s));int n=0;for(Models.Contract c:state.contracts.values()){if(mine&&!me.equals(c.creator)&&!me.equals(c.acceptor))continue;if(!mine&&c.status!=Models.ContractStatus.OPEN)continue;msg(s,"§e#"+c.id+" §f"+c.type+" §7— §a$"+money(c.reward)+" §8| §7"+c.status+" §8| §f"+c.target);if(++n>=20)break;}if(n==0)msg(s,"§7Nessun contratto.");}
    private void ensureAcceptor(Models.Contract c,UUID id){if(c.status!=Models.ContractStatus.ACCEPTED||!id.equals(c.acceptor))throw new IllegalArgumentException("Non sei l'esecutore di questo contratto");}
    private void completeContract(Models.Contract c,Object accepter){if(c.status!=Models.ContractStatus.ACCEPTED)throw new IllegalArgumentException("Contratto non attivo");if(!economy.deposit(c.acceptor,c.reward))throw new IllegalArgumentException("Pagamento Vault/TNE fallito");c.status=Models.ContractStatus.COMPLETED;c.completedAt=System.currentTimeMillis();Models.Stats st=stat(accepter);st.contracts++;st.moneyEarned+=c.reward;Models.Rep r=repOf(c.acceptor);if(Set.of("delivery","vehicle","transport","escort").contains(c.type))r.civil+=3;else if(Set.of("bounty","eliminate","capture").contains(c.type))r.military+=4;state.influence.merge(c.acceptorFaction,25L,Long::sum);dirty=true;broadcast("§8[§eContratti§8] §f"+c.acceptorName+" §7ha completato §e"+c.type+" §7#§f"+c.id+" §7e riceve §a$"+money(c.reward));}

    private void airdropCmd(Object s,List<String>a)throws Exception{String sub=a.size()>1?a.get(1).toLowerCase(Locale.ROOT):"status";long now=System.currentTimeMillis();switch(sub){case"status"->{if(activeAirdrop(now)){Models.Loc l=dropPoint();msg(s,"§bAirdrop §f"+l.name+" §7a §f"+(int)l.x+" "+(int)l.y+" "+(int)l.z+" §7("+minsLeft(state.airdrop.expiresAt,now)+"m)");}else msg(s,"§7Nessun airdrop attivo. Prossimo tra §f"+minsLeft(state.nextAirdropAt,now)+"m§7.");}case"claim"->{if(!activeAirdrop(now))throw new IllegalArgumentException("Nessun airdrop attivo");Object p=player(s);Models.Loc l=R.loc(p);if(dropPoint().dist2(l.dimension,l.x,l.y,l.z)>12*12)throw new IllegalArgumentException("Devi essere entro 12 blocchi dall'airdrop");claimAirdrop(p);}case"add"->{requireOp(s);Object p=player(s);String id=a.size()>2?safeId(a.get(2)):nextId("drop",state.airdropPoints.keySet());Models.Loc l=R.loc(p);l.name=a.size()>3?join(a,3):"Airdrop "+id;state.airdropPoints.put(id,l);dirty=true;msg(s,"§aPunto airdrop §f"+id+" §asalvato.");}case"start"->{requireOp(s);startAirdrop(now);}default->throw new IllegalArgumentException("/no airdrop status|claim|add|start");}}
    private boolean activeAirdrop(long now){return state.airdrop!=null&&!state.airdrop.pointId.isBlank()&&!state.airdrop.claimed&&state.airdrop.expiresAt>now&&state.airdropPoints.containsKey(state.airdrop.pointId);}
    private Models.Loc dropPoint(){return state.airdropPoints.get(state.airdrop.pointId);}
    private void startAirdrop(long now){if(state.airdropPoints.isEmpty()){state.nextAirdropAt=now+min("airdrop.everyMinutes",90)*60_000L;return;}List<String> ids=new ArrayList<>(state.airdropPoints.keySet());String id=ids.get((int)Math.floorMod(now/1000,ids.size()));Models.Airdrop d=new Models.Airdrop();d.pointId=id;d.spawnedAt=now;d.expiresAt=now+min("airdrop.durationMinutes",20)*60_000L;state.airdrop=d;Models.Loc l=state.airdropPoints.get(id);runCommand("setblock "+(int)l.x+" "+(int)l.y+" "+(int)l.z+" minecraft:barrel replace");broadcast("§8[§bAirdrop§8] §bRifornimenti in arrivo: §f"+l.name+" §7("+(int)l.x+", "+(int)l.y+", "+(int)l.z+")");dirty=true;}
    private void claimAirdrop(Object p){long now=System.currentTimeMillis();Models.Loc l=dropPoint();state.airdrop.claimed=true;double reward=cfg.d("airdrop.rewardMoney",2500,0,10_000_000);if(reward>0)economy.deposit(R.uuid(p),reward);for(String cmd:cfg.s("airdrop.rewardCommands","").split(";")){cmd=cmd.trim();if(!cmd.isEmpty())runCommand(cmd.replace("{player}",R.name(p)));}runCommand("setblock "+(int)l.x+" "+(int)l.y+" "+(int)l.z+" minecraft:air replace");Models.Stats st=stat(p);st.airdrops++;st.loot++;st.moneyEarned+=reward;state.nextAirdropAt=now+min("airdrop.everyMinutes",90)*60_000L;dirty=true;broadcast("§8[§bAirdrop§8] §f"+R.name(p)+" §7ha recuperato il carico di §b"+l.name+"§7.");}

    private void convoyCmd(Object s,List<String>a)throws Exception{String sub=a.size()>1?a.get(1).toLowerCase(Locale.ROOT):"status";switch(sub){case"status"->msg(s,"§6Convoglio: §f"+state.convoy.phase+(state.convoy.routeId.isBlank()?"":" §7route §f"+state.convoy.routeId)+(state.convoy.driverName.isBlank()?"":" §7autista §f"+state.convoy.driverName));case"join"->{Object p=player(s);if(state.convoy.phase!=Models.ConvoyPhase.RECRUITING)throw new IllegalArgumentException("Nessun convoglio in reclutamento");if(state.convoy.driver!=null)throw new IllegalArgumentException("Autista già selezionato");Models.Route r=state.routes.get(state.convoy.routeId);Models.Loc l=R.loc(p);if(r==null||r.start.dist2(l.dimension,l.x,l.y,l.z)>20*20)throw new IllegalArgumentException("Vai al punto di partenza");if(cfg.b("convoy.requireMtsVehicle",true)&&!isMtsMounted(p))throw new IllegalArgumentException("Devi essere su un veicolo MTS");state.convoy.driver=R.uuid(p);state.convoy.driverName=R.name(p);state.convoy.driverFaction=towny.faction(p);dirty=true;broadcast("§8[§6Convoglio§8] §f"+R.name(p)+" §7si è candidato come autista.");}case"claim"->{Object p=player(s);if(state.convoy.phase!=Models.ConvoyPhase.CONTESTED||state.convoy.contestedAt==null)throw new IllegalArgumentException("Nessun carico conteso");Models.Loc l=R.loc(p);if(state.convoy.contestedAt.dist2(l.dimension,l.x,l.y,l.z)>12*12)throw new IllegalArgumentException("Non sei vicino al carico");double reward=cfg.d("convoy.stealRewardMoney",7500,0,10_000_000);economy.deposit(R.uuid(p),reward);stat(p).loot++;stat(p).moneyEarned+=reward;repOf(R.uuid(p)).criminal+=3;broadcast("§8[§6Convoglio§8] §f"+R.name(p)+" §7ha sottratto il carico conteso.");finishConvoy(System.currentTimeMillis());}case"startpoint","endpoint"->{requireOp(s);if(a.size()<3)throw new IllegalArgumentException("/no convoy "+sub+" <route>");String id=safeId(a.get(2));Models.Route r=state.routes.computeIfAbsent(id,k->{Models.Route q=new Models.Route();q.id=id;q.name=id;return q;});Models.Loc l=R.loc(player(s));l.name=id+(sub.equals("startpoint")?" start":" end");if(sub.equals("startpoint"))r.start=l;else r.end=l;dirty=true;msg(s,"§a"+sub+" salvato per §f"+id);}case"start"->{requireOp(s);startConvoy(System.currentTimeMillis(),a.size()>2?a.get(2):null);}default->throw new IllegalArgumentException("/no convoy status|join|claim|startpoint|endpoint|start");}}
    private void startConvoy(long now,String forced){List<Models.Route> valid=state.routes.values().stream().filter(r->r.start!=null&&r.end!=null).toList();if(valid.isEmpty()){state.nextConvoyAt=now+min("convoy.everyMinutes",120)*60_000L;return;}Models.Route r=forced==null?valid.get((int)Math.floorMod(now/1000,valid.size())):state.routes.get(forced);if(r==null||r.start==null||r.end==null)throw new IllegalArgumentException("Route non valida");Models.Convoy c=new Models.Convoy();c.phase=Models.ConvoyPhase.RECRUITING;c.routeId=r.id;c.recruitEndsAt=now+min("convoy.recruitMinutes",3)*60_000L;c.expiresAt=c.recruitEndsAt+min("convoy.durationMinutes",30)*60_000L;state.convoy=c;broadcast("§8[§6Convoglio§8] §eCercasi autista MTS per route §f"+r.id+"§e. Partenza tra "+min("convoy.recruitMinutes",3)+" min. §f/no convoy join");dirty=true;}
    private void finishConvoy(long now){state.convoy=new Models.Convoy();state.nextConvoyAt=now+min("convoy.everyMinutes",120)*60_000L;lastDriverLoc=null;dirty=true;}

    private void garageCmd(Object s,List<String>a)throws Exception{String sub=a.size()>1?a.get(1).toLowerCase(Locale.ROOT):"list";Object p=player(s);UUID id=R.uuid(p);Map<String,Models.VehicleAsset> own=state.vehicles.computeIfAbsent(id,k->new LinkedHashMap<>());switch(sub){case"list"->{if(own.isEmpty()){msg(s,"§7Nessun veicolo registrato.");return;}for(Models.VehicleAsset v:own.values())msg(s,"§e"+v.key+" §f"+v.displayName+" §8| §7targa §f"+v.plate+" §8| §7km §f"+String.format(Locale.ROOT,"%.1f",v.km)+" §8| §7cond. §f"+v.condition+"%"+(v.insuranceUntil>System.currentTimeMillis()?" §aASSICURATO":"")+(listed(id,v.key)?" §6IN VENDITA":""));}case"insure"->{if(a.size()<3)throw new IllegalArgumentException("/no garage insure <key>");Models.VehicleAsset v=vehicle(own,a.get(2));double price=cfg.d("garage.insurancePrice",2500,0,10_000_000);if(!economy.withdraw(id,price))throw new IllegalArgumentException("Saldo insufficiente");v.insuranceUntil=System.currentTimeMillis()+cfg.l("garage.insuranceDays",7,1,365)*86400_000L;stat(p).moneySpent+=price;state.totalMoneySunk+=Math.round(price);dirty=true;msg(s,"§aPolizza attiva fino a §f"+Instant.ofEpochMilli(v.insuranceUntil));}case"prepare"->{if(a.size()<3)throw new IllegalArgumentException("/no garage prepare <key>");Models.VehicleAsset v=vehicle(own,a.get(2));if(listed(id,v.key))throw new IllegalArgumentException("Veicolo attualmente in vendita");long now=System.currentTimeMillis(),cool=cfg.l("garage.spawnCooldownSeconds",300,0,86400)*1000L;if(now-v.lastSpawnAt<cool)throw new IllegalArgumentException("Cooldown: "+((cool-(now-v.lastSpawnAt))/1000)+"s");double fee=v.destroyed?(v.insuranceUntil>now?0:cfg.d("garage.recoveryFee",5000,0,10_000_000)):cfg.d("garage.spawnFee",250,0,10_000_000);if(fee>0&&!economy.withdraw(id,fee))throw new IllegalArgumentException("Saldo insufficiente per recupero/spawn");v.lastSpawnAt=now;v.destroyed=false;activeVehicle.put(id,v.key);stat(p).moneySpent+=fee;state.totalMoneySunk+=Math.round(fee);dirty=true;msg(s,"§aVeicolo pronto: §f"+v.displayName+" §7(targa "+v.plate+")§a. Il garage esistente può ora eseguire lo spawn MTS.");}case"grant"->{requireOp(s);if(a.size()<5)throw new IllegalArgumentException("/no garage grant <player> <key> <nome>");Object target=findPlayer(a.get(2));if(target==null)throw new IllegalArgumentException("Player online non trovato");UUID tid=R.uuid(target);Map<String,Models.VehicleAsset> m=state.vehicles.computeIfAbsent(tid,k->new LinkedHashMap<>());String key=safeId(a.get(3));if(m.containsKey(key))throw new IllegalArgumentException("Veicolo già registrato");Models.VehicleAsset v=new Models.VehicleAsset();v.key=key;v.displayName=join(a,4);v.plate=plate();v.acquiredAt=System.currentTimeMillis();m.put(key,v);stat(target).vehiclesBought++;dirty=true;msg(s,"§aRegistrato §f"+v.displayName+" §aa §f"+R.name(target));}case"destroyed"->{requireOp(s);if(a.size()<4)throw new IllegalArgumentException("/no garage destroyed <player> <key>");Object target=findPlayer(a.get(2));if(target==null)throw new IllegalArgumentException("Player online non trovato");vehicle(state.vehicles.getOrDefault(R.uuid(target),Map.of()),a.get(3)).destroyed=true;dirty=true;}default->throw new IllegalArgumentException("/no garage list|insure|prepare|grant|destroyed");}}
    private Models.VehicleAsset vehicle(Map<String,Models.VehicleAsset> own,String key){Models.VehicleAsset v=own.get(key);if(v==null)throw new IllegalArgumentException("Veicolo non posseduto: "+key);return v;}
    private boolean listed(UUID owner,String key){return state.usedListings.values().stream().anyMatch(x->x.seller.equals(owner)&&x.vehicleKey.equals(key));}

    private void usedCmd(Object s,List<String>a)throws Exception{String sub=a.size()>1?a.get(1).toLowerCase(Locale.ROOT):"list";Object p=player(s);UUID me=R.uuid(p);switch(sub){case"list"->{int n=0;for(Models.UsedListing x:state.usedListings.values()){msg(s,"§e#"+x.id+" §f"+x.vehicleName+" §7["+x.plate+"] §8| §a$"+money(x.price)+" §8| §7"+x.sellerName);if(++n>=20)break;}if(n==0)msg(s,"§7Nessun veicolo usato in vendita.");}case"sell"->{if(a.size()<4)throw new IllegalArgumentException("/no usato sell <vehicleKey> <prezzo>");Map<String,Models.VehicleAsset> own=state.vehicles.getOrDefault(me,Map.of());Models.VehicleAsset v=vehicle(own,a.get(2));if(listed(me,v.key))throw new IllegalArgumentException("Già in vendita");double price=Double.parseDouble(a.get(3));if(price<=0||price>100_000_000)throw new IllegalArgumentException("Prezzo non valido");Models.UsedListing x=new Models.UsedListing();x.id=shortId();x.vehicleKey=v.key;x.vehicleName=v.displayName;x.plate=v.plate;x.seller=me;x.sellerName=R.name(p);x.price=price;x.createdAt=System.currentTimeMillis();x.expiresAt=x.createdAt+cfg.l("used.listingHours",168,1,720)*3600_000L;state.usedListings.put(x.id,x);dirty=true;broadcast("§8[§6Usato§8] §f"+x.vehicleName+" §7["+x.plate+"] in vendita a §a$"+money(price)+" §7#§f"+x.id);}case"buy"->{if(a.size()<3)throw new IllegalArgumentException("/no usato buy <id>");Models.UsedListing x=state.usedListings.get(a.get(2));if(x==null)throw new IllegalArgumentException("Inserzione non trovata");if(me.equals(x.seller))throw new IllegalArgumentException("È il tuo veicolo");Map<String,Models.VehicleAsset> seller=state.vehicles.get(x.seller);if(seller==null||!seller.containsKey(x.vehicleKey))throw new IllegalArgumentException("Proprietà venditore non valida");if(!economy.withdraw(me,x.price))throw new IllegalArgumentException("Saldo insufficiente");double tax=x.price*cfg.d("used.taxPercent",5,0,50)/100.0,net=x.price-tax;if(!economy.deposit(x.seller,net)){economy.deposit(me,x.price);throw new IllegalArgumentException("Pagamento al venditore fallito: acquisto annullato");}Models.VehicleAsset v=seller.remove(x.vehicleKey);state.vehicles.computeIfAbsent(me,k->new LinkedHashMap<>()).put(v.key,v);state.usedListings.remove(x.id);stat(p).vehiclesBought++;Models.Stats ss=state.stats.computeIfAbsent(x.seller,k->new Models.Stats());ss.vehiclesSold++;ss.moneyEarned+=net;stat(p).moneySpent+=x.price;state.totalMoneySunk+=Math.round(tax);dirty=true;broadcast("§8[§6Usato§8] §f"+R.name(p)+" §7ha acquistato §f"+v.displayName+" §7["+v.plate+"] da §f"+x.sellerName+"§7.");}case"cancel"->{if(a.size()<3)throw new IllegalArgumentException("/no usato cancel <id>");Models.UsedListing x=state.usedListings.get(a.get(2));if(x==null||!me.equals(x.seller))throw new IllegalArgumentException("Inserzione non tua");state.usedListings.remove(x.id);dirty=true;msg(s,"§aInserzione ritirata.");}default->throw new IllegalArgumentException("/no usato list|sell|buy|cancel");}}

    private void startTreatment(Object s,String type)throws Exception{Object p=player(s);UUID id=R.uuid(p);long now=System.currentTimeMillis();Models.Injury in=state.injuries.get(id);if(in==null||!in.active(now)){msg(s,"§7Non hai ferite attive.");return;}double cost=type.equals("medical")?cfg.d("medical.cost",1500,0,1_000_000):cfg.d("medical.bandageCost",250,0,1_000_000);if(type.equals("medical")&&repOf(id).civil<cfg.i("medical.minCivilRep",20,-100000,100000))throw new IllegalArgumentException("Serve reputazione Civile "+cfg.i("medical.minCivilRep",20,-100000,100000)+" per il contatto medico");if(cost>0&&!economy.withdraw(id,cost))throw new IllegalArgumentException("Saldo insufficiente");Models.Loc l=R.loc(p);Models.Treatment t=new Models.Treatment();t.player=id;t.type=type;t.dimension=l.dimension;t.x=l.x;t.y=l.y;t.z=l.z;t.endsAt=now+cfg.i("injury.treatmentSeconds",8,2,60)*1000L;treatments.put(id,t);stat(p).moneySpent+=cost;state.totalMoneySunk+=Math.round(cost);dirty=true;send(p,"§eTrattamento iniziato. Non muoverti e non subire danni per "+cfg.i("injury.treatmentSeconds",8,2,60)+"s.");}

    private void livingDamage(Object event){try{Object victim=R.call(event,"getEntity");if(!isPlayer(victim))return;UUID id=R.uuid(victim);if(internalDamage.contains(id))return;double amount=R.num(R.call(event,"getAmount"));Models.Injury in=state.injuries.computeIfAbsent(id,k->new Models.Injury());long now=System.currentTimeMillis();in.lastHitAt=now;if(treatments.remove(id)!=null)send(victim,"§cTrattamento interrotto: hai subito danni.");if(!cfg.b("injury.enabled",true)||amount<cfg.d("injury.minHitDamage",6,0,1000))return;String zone=impactZone(event,victim);in.zone=zone;in.severity=Math.min(3,in.severity+1);long duration=cfg.i("injury.durationSeconds",90,10,1800)*1000L;if(ThreadLocalRandom.current().nextDouble()<cfg.d("injury.bleedChance",0.35,0,1))in.bleedUntil=Math.max(in.bleedUntil,now+duration);if(zone.equals("legs"))in.legUntil=Math.max(in.legUntil,now+duration);if(zone.equals("head"))in.headUntil=Math.max(in.headUntil,now+duration/2);dirty=true;send(victim,"§cFerita: §f"+zone+(in.bleedUntil>now?" §4[SANGUINAMENTO]":"")+"§c. Usa §f/no bendaggio§c o §f/no medico§c.");}catch(Exception ignored){}}
    private String impactZone(Object event,Object victim){try{Object src=R.call(event,"getSource");Object d=R.call(src,"getDirectEntity");if(d==null)return"torso";double y=R.num(R.call(d,"getY"))-R.num(R.call(victim,"getY"));if(y>1.35)return"head";if(y<0.65)return"legs";}catch(Exception ignored){}return"torso";}

    private void livingDeath(Object event){try{Object victim=R.call(event,"getEntity");if(!isPlayer(victim)){if(isMtsEntity(victim))markPassengerVehicleDestroyed(victim);return;}UUID vid=R.uuid(victim);stat(victim).deaths++;Models.Injury in=state.injuries.get(vid);if(in!=null){in.bleedUntil=in.legUntil=in.headUntil=0;in.severity=0;}treatments.remove(vid);
        Object src=R.call(event,"getSource");Object killer=null;try{killer=R.call(src,"getEntity");}catch(Exception ignored){}if(killer==null||!isPlayer(killer)||R.uuid(killer).equals(vid))return;UUID kid=R.uuid(killer);if(cfg.b("pvp.ignoreSameTownOrNation",true)&&towny.allied(killer,victim))return;long now=System.currentTimeMillis();String key=kid+":"+vid;long cd=cfg.i("pvp.repeatVictimMinutes",10,0,1440)*60_000L;if(now-state.pvpCooldown.getOrDefault(key,0L)<cd)return;state.pvpCooldown.put(key,now);stat(killer).kills++;Models.Rep kr=repOf(kid);kr.military+=3;kr.criminal+=1;String faction=towny.faction(killer);state.influence.merge(faction,10L,Long::sum);autoCompleteKillContracts(killer,victim);if(state.convoy.phase==Models.ConvoyPhase.ENROUTE&&vid.equals(state.convoy.driver)){state.convoy.phase=Models.ConvoyPhase.CONTESTED;state.convoy.contestedAt=R.loc(victim);broadcast("§8[§6Convoglio§8] §cAutista abbattuto: il carico è conteso alle coordinate §f"+(int)state.convoy.contestedAt.x+" "+(int)state.convoy.contestedAt.y+" "+(int)state.convoy.contestedAt.z+"§c.");}dirty=true;
    }catch(Exception ignored){}}
    private void autoCompleteKillContracts(Object killer,Object victim){String victimName=R.name(victim);UUID kid=R.uuid(killer);for(Models.Contract c:state.contracts.values())if(c.status==Models.ContractStatus.ACCEPTED&&kid.equals(c.acceptor)&&Set.of("bounty","eliminate").contains(c.type)&&c.target.equalsIgnoreCase(victimName)){try{completeContract(c,killer);}catch(Exception e){send(killer,"§cContratto #"+c.id+" completato sul campo ma pagamento fallito: "+R.root(e));}}}

    private void tickStrategic(long now){List<?> players=online();int cap=cfg.i("captureSeconds",120,10,3600);for(Models.Point point:state.points.values()){Map<String,List<Object>> present=new LinkedHashMap<>();for(Object p:players)try{if(!R.alive(p)||R.spectator(p))continue;Models.Loc l=R.loc(p);if(point.loc.dist2(l.dimension,l.x,l.y,l.z)<=point.radius*point.radius)present.computeIfAbsent(towny.faction(p),k->new ArrayList<>()).add(p);}catch(Exception ignored){}if(present.size()!=1)continue;String f=present.keySet().iterator().next();if(f.equals(point.owner)){if(!point.candidate.isBlank()||point.progress!=0){point.candidate="";point.progress=0;dirty=true;}continue;}if(!f.equals(point.candidate)){point.candidate=f;point.progress=1;}else point.progress++;dirty=true;if(point.progress>=cap){String prev=point.owner;point.owner=f;point.candidate="";point.progress=0;state.influence.putIfAbsent(f,0L);for(Object p:present.get(f)){stat(p).strategicCaptures++;repOf(R.uuid(p)).military+=3;}broadcast("§8[§cStrategia§8] §f"+f+" §7ha conquistato §e"+point.name+(prev.isBlank()?"§7.":" §7da §f"+prev+"§7."));autoCompleteCaptureContracts(point.id,f,present.get(f));dirty=true;}}}
    private void autoCompleteCaptureContracts(String point,String faction,List<Object> players){for(Models.Contract c:state.contracts.values())if(c.status==Models.ContractStatus.ACCEPTED&&c.type.equals("capture")&&c.target.equalsIgnoreCase(point)&&c.acceptorFaction.equalsIgnoreCase(faction)){Object p=players.stream().filter(x->R.uuid(x).equals(c.acceptor)).findFirst().orElse(findPlayer(c.acceptorName));if(p!=null)try{completeContract(c,p);}catch(Exception ignored){}}}
    private void tickEvents(long now){if(state.eventEndsAt>0&&now>=state.eventEndsAt){broadcast("§8[§6Evento§8] §7Evento strategico terminato.");state.eventPoint="";state.eventEndsAt=0;state.nextStrategicEventAt=now+min("event.everyMinutes",45)*60_000L;dirty=true;}if(state.eventEndsAt<=0&&now>=state.nextStrategicEventAt&&!state.points.isEmpty())startStrategicEvent(now);}
    private void startStrategicEvent(long now){if(state.points.isEmpty())throw new IllegalArgumentException("Nessun punto strategico");List<Models.Point> l=new ArrayList<>(state.points.values());Models.Point p=l.get((int)Math.floorMod(now/1000,l.size()));state.eventPoint=p.id;state.eventEndsAt=now+min("event.durationMinutes",15)*60_000L;state.nextStrategicEventAt=state.eventEndsAt+min("event.everyMinutes",45)*60_000L;broadcast("§8[§6Evento§8] §eOBIETTIVO CALDO: §f"+p.name+" §7vale §6x"+cfg.i("event.scoreMultiplier",2,1,10)+" §7influenza.");dirty=true;}
    private void tickInfluence(long now){long every=cfg.i("strategic.scoreEverySeconds",60,10,3600)*1000L;if(state.lastScoreAt>0&&now-state.lastScoreAt<every)return;state.lastScoreAt=now;int base=cfg.i("strategic.scorePerPoint",10,1,100000),multi=cfg.i("event.scoreMultiplier",2,1,10);for(Models.Point p:state.points.values())if(!p.owner.isBlank())state.influence.merge(p.owner,(long)(base*((state.eventEndsAt>now&&p.id.equals(state.eventPoint))?multi:1)),Long::sum);checkSeason(now);dirty=true;}
    private void checkSeason(long now){long target=cfg.l("season.targetScore",2500,1,Long.MAX_VALUE);var champ=state.influence.entrySet().stream().max(Map.Entry.comparingByValue()).orElse(null);if(champ==null||champ.getValue()<target)return;int star=state.legacy.merge(champ.getKey(),1,Integer::sum);broadcast("§8[§dENDGAME§8] §f"+champ.getKey()+" §7vince la campagna con §d"+champ.getValue()+" §7influenza e ottiene §dLegacy "+star+"§7!");if(cfg.b("season.autoReset",true)){state.influence.replaceAll((k,v)->0L);for(Models.Point p:state.points.values()){p.owner="";p.candidate="";p.progress=0;}state.eventPoint="";state.eventEndsAt=0;state.nextStrategicEventAt=now+min("event.everyMinutes",45)*60_000L;broadcast("§8[§dENDGAME§8] §7Nuova campagna iniziata. Denaro, inventari e costruzioni NON sono stati resettati.");}dirty=true;}

    private void tickInjuries(long now){for(Object p:online())try{UUID id=R.uuid(p);Models.Injury in=state.injuries.get(id);if(in==null)continue;if(in.bleedUntil>now&&now-in.lastBleedDamageAt>=5000){in.lastBleedDamageAt=now;internalDamage.add(id);try{runCommand("damage "+R.name(p)+" 1 minecraft:generic");}finally{internalDamage.remove(id);}dirty=true;}if(in.legUntil>now)runCommand("effect give "+R.name(p)+" minecraft:slowness 2 0 true");if(in.headUntil>now)runCommand("effect give "+R.name(p)+" minecraft:nausea 2 0 true");if(!in.active(now)&&in.severity!=0){in.severity=0;dirty=true;}}catch(Exception ignored){}}
    private void tickTreatments(long now){Iterator<Map.Entry<UUID,Models.Treatment>> it=treatments.entrySet().iterator();while(it.hasNext()){var e=it.next();Object p=findPlayerByUuid(e.getKey());if(p==null){it.remove();continue;}Models.Treatment t=e.getValue();try{Models.Loc l=R.loc(p);if(!Objects.equals(l.dimension,t.dimension)||dist2(l.x,l.y,l.z,t.x,t.y,t.z)>1.5*1.5){send(p,"§cTrattamento interrotto: ti sei mosso.");it.remove();continue;}if(now>=t.endsAt){Models.Injury in=state.injuries.computeIfAbsent(e.getKey(),k->new Models.Injury());if(t.type.equals("bandage"))in.bleedUntil=0;else{in.bleedUntil=in.legUntil=in.headUntil=0;in.severity=0;}send(p,"§aTrattamento completato.");it.remove();dirty=true;}}catch(Exception ex){it.remove();}}}
    private void tickAirdrop(long now){if(activeAirdrop(now))return;if(state.airdrop!=null&&!state.airdrop.pointId.isBlank()&&!state.airdrop.claimed&&state.airdrop.expiresAt<=now){Models.Loc l=dropPoint();if(l!=null)runCommand("setblock "+(int)l.x+" "+(int)l.y+" "+(int)l.z+" minecraft:air replace");state.airdrop=new Models.Airdrop();state.nextAirdropAt=now+min("airdrop.everyMinutes",90)*60_000L;dirty=true;}if(now>=state.nextAirdropAt&&!state.airdropPoints.isEmpty())startAirdrop(now);}
    private void tickConvoy(long now){Models.Convoy c=state.convoy;if(c.phase==Models.ConvoyPhase.NONE){if(now>=state.nextConvoyAt)startConvoy(now,null);return;}if(c.phase==Models.ConvoyPhase.RECRUITING&&now>=c.recruitEndsAt){Object d=c.driver==null?null:findPlayerByUuid(c.driver);Models.Route r=state.routes.get(c.routeId);if(d==null||r==null||(cfg.b("convoy.requireMtsVehicle",true)&&!isMtsMounted(d))){broadcast("§8[§6Convoglio§8] §cPartenza annullata: nessun autista MTS valido.");finishConvoy(now);return;}c.phase=Models.ConvoyPhase.ENROUTE;c.startedAt=now;broadcast("§8[§6Convoglio§8] §aConvoglio partito con §f"+c.driverName+"§a.");dirty=true;}if(c.phase==Models.ConvoyPhase.ENROUTE){Object d=findPlayerByUuid(c.driver);if(d==null){if(lastDriverLoc!=null){c.phase=Models.ConvoyPhase.CONTESTED;c.contestedAt=lastDriverLoc;broadcast("§8[§6Convoglio§8] §cAutista disconnesso: carico conteso.");dirty=true;}else finishConvoy(now);return;}try{lastDriverLoc=R.loc(d);Models.Route r=state.routes.get(c.routeId);if(r!=null&&r.end.dist2(lastDriverLoc.dimension,lastDriverLoc.x,lastDriverLoc.y,lastDriverLoc.z)<=18*18&&(!cfg.b("convoy.requireMtsVehicle",true)||isMtsMounted(d))){double reward=cfg.d("convoy.rewardMoney",10000,0,10_000_000);economy.deposit(c.driver,reward);Models.Stats st=stat(d);st.convoys++;st.moneyEarned+=reward;Models.Rep rep=repOf(c.driver);rep.civil+=2;rep.military+=2;long inf=cfg.l("convoy.influenceReward",100,0,1_000_000);state.influence.merge(c.driverFaction,inf,Long::sum);broadcast("§8[§6Convoglio§8] §aCarico consegnato da §f"+c.driverName+"§a: §f$"+money(reward)+" §7+"+inf+" influenza.");finishConvoy(now);return;}}catch(Exception ignored){}if(now>=c.expiresAt){broadcast("§8[§6Convoglio§8] §cConvoglio fallito: tempo scaduto.");finishConvoy(now);}}else if(c.phase==Models.ConvoyPhase.CONTESTED&&now>=c.expiresAt){broadcast("§8[§6Convoglio§8] §7Carico conteso disperso.");finishConvoy(now);}}
    private void tickVehicleKm(long now){for(Object p:online())try{UUID id=R.uuid(p);if(!isMtsMounted(p)){lastMtsLoc.remove(id);continue;}Models.Loc cur=R.loc(p),prev=lastMtsLoc.put(id,cur);if(prev==null||!Objects.equals(prev.dimension,cur.dimension))continue;double blocks=Math.sqrt(dist2(cur.x,cur.y,cur.z,prev.x,prev.y,prev.z));if(blocks>80)continue;double km=blocks/1000.0;Models.Stats st=stat(p);st.mtsKm+=km;String key=activeVehicle.get(id);Map<String,Models.VehicleAsset> own=state.vehicles.get(id);if(own!=null){if(key==null&&own.size()==1)key=own.keySet().iterator().next();if(key!=null&&own.containsKey(key))own.get(key).km+=km;}if(km>0.0001)dirty=true;}catch(Exception ignored){}}
    private void tickExpiry(long now){for(Models.Contract c:state.contracts.values())if((c.status==Models.ContractStatus.OPEN||c.status==Models.ContractStatus.ACCEPTED)&&c.expiresAt<=now){if(economy.deposit(c.creator,c.reward)){c.status=Models.ContractStatus.EXPIRED;dirty=true;}}Iterator<Models.UsedListing> ui=state.usedListings.values().iterator();while(ui.hasNext())if(ui.next().expiresAt<=now){ui.remove();dirty=true;}long prune=now-cfg.i("pvp.repeatVictimMinutes",10,0,1440)*60_000L*3;state.pvpCooldown.entrySet().removeIf(e->e.getValue()<prune);}

    private boolean isMtsMounted(Object player){try{Object v=R.call(player,"getVehicle");return v!=null&&isMtsEntity(v);}catch(Exception e){return false;}}
    private boolean isMtsEntity(Object x){if(x==null)return false;String n=x.getClass().getName().toLowerCase(Locale.ROOT);return n.contains("minecrafttransportsimulator")||n.contains("immersivevehicles")||n.contains("mts");}
    private void markPassengerVehicleDestroyed(Object vehicle){try{Object passengers=R.call(vehicle,"getPassengers");if(passengers instanceof Iterable<?> it)for(Object p:it)if(isPlayer(p)){UUID id=R.uuid(p);String key=activeVehicle.get(id);Map<String,Models.VehicleAsset> own=state.vehicles.get(id);if(key!=null&&own!=null&&own.containsKey(key)){own.get(key).destroyed=true;dirty=true;}}}catch(Exception ignored){}}

    private boolean isPlayer(Object x){if(x==null)return false;try{return Class.forName("net.minecraft.world.entity.player.Player").isInstance(x);}catch(Throwable e){String n=x.getClass().getName();return n.endsWith("ServerPlayer")||n.endsWith("Player");}}
    private Object player(Object source)throws Exception{return R.call(source,"getPlayerOrException");}
    private boolean isOp(Object source){try{return Boolean.TRUE.equals(R.call(source,"hasPermission",2));}catch(Exception e){return false;}}
    private void requireOp(Object source){if(!isOp(source))throw new IllegalArgumentException("Permessi insufficienti");}
    private List<?> online(){try{return (List<?>)R.call(R.call(server,"getPlayerList"),"getPlayers");}catch(Exception e){return List.of();}}
    private Object findPlayer(String name){for(Object p:online())if(R.name(p).equalsIgnoreCase(name))return p;return null;}
    private Object findPlayerByUuid(UUID id){for(Object p:online())if(R.uuid(p).equals(id))return p;return null;}
    private Models.Stats stat(Object p){UUID id=R.uuid(p);Models.Stats s=state.stats.computeIfAbsent(id,k->new Models.Stats());s.lastName=R.name(p);return s;}
    private Models.Rep repOf(UUID id){return state.reputation.computeIfAbsent(id,k->new Models.Rep());}
    private int vehicleCount(UUID id){return state.vehicles.getOrDefault(id,Map.of()).size();}
    private boolean townyAvailable(){try{Class.forName("com.palmergames.bukkit.towny.TownyAPI");return true;}catch(Throwable e){return false;}}

    private void applyTaczShootCompatibilityFix(){
        int result=runCommand("tacz config serverShootNetworkCheck false");
        if(result>0)LOG.log(System.Logger.Level.INFO,"TaCZ: serverShootNetworkCheck disabilitato per evitare il blocco iniziale dello sparo.");
        else LOG.log(System.Logger.Level.INFO,"Comando compatibilita TaCZ non disponibile; nessuna modifica applicata.");
    }

    private int runCommand(String cmd){if(server==null)return 0;try{Object source=R.call(server,"createCommandSourceStack");Object commands=R.call(server,"getCommands");for(String method:List.of("performPrefixedCommand","performCommand","m_230957_"))try{Object r=R.call(commands,method,source,cmd);return r instanceof Number n?n.intValue():1;}catch(Exception ignored){}return 0;}catch(Exception e){return 0;}}
    private void broadcast(String text){if(server==null){LOG.log(System.Logger.Level.INFO,text.replaceAll("§.",""));return;}try{Object pl=R.call(server,"getPlayerList");Object c=R.component(text);for(Method m:pl.getClass().getMethods())if(m.getName().equals("broadcastSystemMessage")&&m.getParameterCount()==2){try{m.invoke(pl,c,false);return;}catch(Exception ignored){}}}catch(Exception ignored){}for(Object p:online())send(p,text);}
    private void send(Object target,String text){try{Object c=R.component(text);for(Method m:target.getClass().getMethods())if(m.getName().equals("sendSystemMessage")&&m.getParameterCount()==1){try{m.invoke(target,c);return;}catch(Exception ignored){}}for(Method m:target.getClass().getMethods())if(m.getName().equals("sendSuccess")&&m.getParameterCount()==2){java.util.function.Supplier<Object> s=()->c;try{m.invoke(target,s,false);return;}catch(Exception ignored){}}}catch(Exception ignored){}}
    private void msg(Object s,String t){send(s,t);}
    private synchronized void save(){try{store.save(state);lastSaveAt=System.currentTimeMillis();dirty=false;}catch(Exception e){LOG.log(System.Logger.Level.ERROR,"Salvataggio stato fallito",e);}}

    private String hubJson(){synchronized(this){StringBuilder b=new StringBuilder(8192);b.append('{');kv(b,"version",VERSION).append(',');kv(b,"timestamp",System.currentTimeMillis()).append(',');kv(b,"online",online().size()).append(',');kv(b,"moneySunk",state.totalMoneySunk).append(',');b.append("\"event\":");if(state.eventEndsAt>System.currentTimeMillis()&&state.points.containsKey(state.eventPoint)){Models.Point p=state.points.get(state.eventPoint);b.append('{');kv(b,"point",p.id).append(',');kv(b,"name",p.name).append(',');kv(b,"endsAt",state.eventEndsAt);b.append('}');}else b.append("null");b.append(',');b.append("\"influence\":[");List<Map.Entry<String,Long>> inf=new ArrayList<>(state.influence.entrySet());inf.sort((x,y)->Long.compare(y.getValue(),x.getValue()));for(int i=0;i<Math.min(20,inf.size());i++){if(i>0)b.append(',');var e=inf.get(i);b.append('{');kv(b,"name",e.getKey()).append(',');kv(b,"score",e.getValue()).append(',');kv(b,"legacy",state.legacy.getOrDefault(e.getKey(),0));b.append('}');}b.append("],\"players\":[");List<Models.Stats> st=new ArrayList<>(state.stats.values());st.sort((x,y)->Long.compare(y.kills,x.kills));for(int i=0;i<Math.min(50,st.size());i++){if(i>0)b.append(',');Models.Stats x=st.get(i);b.append('{');kv(b,"name",x.lastName).append(',');kv(b,"kills",x.kills).append(',');kv(b,"deaths",x.deaths).append(',');kv(b,"contracts",x.contracts).append(',');kv(b,"loot",x.loot).append(',');kv(b,"convoys",x.convoys).append(',');kv(b,"mtsKm",Math.round(x.mtsKm*100.0)/100.0);b.append('}');}b.append("],\"used\":[");int ui=0;for(Models.UsedListing x:state.usedListings.values()){if(ui++>0)b.append(',');b.append('{');kv(b,"id",x.id).append(',');kv(b,"vehicle",x.vehicleName).append(',');kv(b,"plate",x.plate).append(',');kv(b,"seller",x.sellerName).append(',');kv(b,"price",x.price);b.append('}');if(ui>=50)break;}b.append("],");kv(b,"openContracts",state.contracts.values().stream().filter(x->x.status==Models.ContractStatus.OPEN).count()).append(',');kv(b,"convoy",state.convoy.phase.toString()).append(',');kv(b,"airdrop",activeAirdrop(System.currentTimeMillis())?dropPoint().name:"");b.append('}');return b.toString();}}
    private static StringBuilder kv(StringBuilder b,String k,Object v){b.append('"').append(j(k)).append("\":");if(v==null)b.append("null");else if(v instanceof Number||v instanceof Boolean)b.append(v);else b.append('"').append(j(String.valueOf(v))).append('"');return b;}
    private static String j(String s){return s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","");}

    private static List<String> tokens(String s){List<String> out=new ArrayList<>();StringBuilder b=new StringBuilder();boolean q=false;char quote=0;for(int i=0;i<s.length();i++){char c=s.charAt(i);if((c=='\"'||c=='\'')&&!q){q=true;quote=c;continue;}if(q&&c==quote){q=false;continue;}if(Character.isWhitespace(c)&&!q){if(b.length()>0){out.add(b.toString());b.setLength(0);}}else b.append(c);}if(b.length()>0)out.add(b.toString());return out;}
    private static String join(List<String>a,int from){return String.join(" ",a.subList(from,a.size()));}
    private static String safeId(String s){String x=s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9_-]","_");if(x.isBlank()||x.length()>40)throw new IllegalArgumentException("ID non valido");return x;}
    private static String nextId(String prefix,Collection<String> existing){int i=1;while(existing.contains(prefix+i))i++;return prefix+i;}
    private static String shortId(){return UUID.randomUUID().toString().substring(0,8);}
    private static String plate(){String a="ABCDEFGHJKLMNPRSTUVWXYZ";Random r=ThreadLocalRandom.current();return "NO-"+a.charAt(r.nextInt(a.length()))+a.charAt(r.nextInt(a.length()))+"-"+(100+r.nextInt(900));}
    private long min(String key,long def){return cfg.l(key,def,1,7*24*60);}
    private static long minsLeft(long at,long now){return Math.max(0,(at-now+59_999)/60_000);}
    private static double dist2(double x,double y,double z,double a,double b,double c){double dx=x-a,dy=y-b,dz=z-c;return dx*dx+dy*dy+dz*dz;}
    private static String money(double d){return String.format(Locale.ROOT,"%,.0f",d);}
    private static String format(double d){return Math.abs(d-Math.rint(d))<0.001?String.format(Locale.ROOT,"%,.0f",d):String.format(Locale.ROOT,"%,.2f",d);}
}
